// Package inventory 判定低库存。这是一个评测 fixture，不是生产代码。
package inventory

import (
	"encoding/json"
	"os"
	"path/filepath"
	"sort"
)

// DefaultLowStockThreshold 是所有**未配置**仓库共用的低库存阈值。
const DefaultLowStockThreshold = 5

// thresholdsPath 是阈值配置相对仓库根的位置。测试可以把它指向临时文件。
var thresholdsPath = "config/thresholds.json"

// LowStockThreshold 返回这个仓库的低库存阈值：优先取 config/thresholds.json
// 里该仓库配的值；没配、文件不存在、读不出来或内容不是 JSON 对象时，一律回退
// DefaultLowStockThreshold。
func LowStockThreshold(warehouse string) int {
	thresholds, err := loadThresholds()
	if err != nil {
		return DefaultLowStockThreshold
	}
	if threshold, ok := thresholds[warehouse]; ok {
		return threshold
	}
	return DefaultLowStockThreshold
}

// loadThresholds 读取阈值配置；任何读取或解析失败都返回错误，由调用方回退。
func loadThresholds() (map[string]int, error) {
	data, err := os.ReadFile(resolveThresholdsPath())
	if err != nil {
		return nil, err
	}
	var thresholds map[string]int
	if err := json.Unmarshal(data, &thresholds); err != nil {
		return nil, err
	}
	return thresholds, nil
}

// resolveThresholdsPath 定位阈值配置：相对路径先按当前工作目录找，找不到再按
// 仓库根（最近的 go.mod 所在目录）找。这样从仓库任意子目录运行都能读到同一份配置。
func resolveThresholdsPath() string {
	if filepath.IsAbs(thresholdsPath) {
		return thresholdsPath
	}
	if _, err := os.Stat(thresholdsPath); err == nil {
		return thresholdsPath
	}
	if root, err := moduleRoot(); err == nil {
		return filepath.Join(root, thresholdsPath)
	}
	return thresholdsPath
}

// moduleRoot 从当前工作目录向上找最近的含 go.mod 的目录。
func moduleRoot() (string, error) {
	dir, err := os.Getwd()
	if err != nil {
		return "", err
	}
	for {
		if _, err := os.Stat(filepath.Join(dir, "go.mod")); err == nil {
			return dir, nil
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return "", os.ErrNotExist
		}
		dir = parent
	}
}
```

